/* Disable only stuns a grounded opponent facing the incoming hit. */
int port_remix_disable_damage(GObj *g){FTStruct *fp=ftGetStruct(g);if(!port_remix_enabled()||fp->damage_element!=8||fp->ga!=nMPKineticsGround||fp->status_id==nFTCommonStatusFuraFura||fp->damage_lr!=fp->lr)return 0;ftCommonFuraFuraSetStatus(g);return 1;}
static void mewtwo_install(FighterDescriptor *d){memcpy(mewtwo_status,safe_statuses,sizeof(mewtwo_status));int actions[]={222,223,224,225,226,228,229,230,234,235,236,237,238,239};int motions[]={197,198,199,200,201,202,203,204,208,-1,209,210,-1,211};for(int i=0;i<14;i++){int a=actions[i],air=a==225||a==226||a==228||a==230||a>=237;FTStatusDesc *s=mewtwo_status+a-220;s->mflags.motion_id=motions[i];s->mflags.attack_id=a<229?18:a<234?30:17;s->sflags.attack_id=s->mflags.attack_id;s->sflags.ga=air;s->proc_update=a==222||a==225?mewtwo_n_start:a==223||a==226?mewtwo_charge_update:a==224||a==228?mewtwo_shoot_update:a==229?ftAnimEndSetWait:a==230?ftAnimEndSetFall:a==234||a==237?mewtwo_h_begin_update:a==235||a==238?mewtwo_h_move_update:mewtwo_h_end_update;s->proc_interrupt=a==222||a==225?ftSamusSpecialNStartProcInterrupt:a==223||a==226?mewtwo_charge_interrupt:NULL;s->proc_physics=a==235||a==238?mewtwo_move_physics:air?(a==225?ftPhysicsApplyAirVelDrift:ftPhysicsApplyAirVelFriction):ftPhysicsApplyGroundVelFriction;s->proc_map=a<229?mewtwo_n_map:a<234?mewtwo_d_map:a==236||a==239?mewtwo_h_end_map:mewtwo_h_map;}
 d->special_descs=mewtwo_status;d->special_handler[0]=mewtwo_ng;d->special_handler[1]=mewtwo_hg;d->special_handler[2]=mewtwo_dg;d->special_handler[3]=mewtwo_na;d->special_handler[4]=mewtwo_ha;d->special_handler[5]=mewtwo_da;
}
